/**
 * Environment schema — architect spec §7.4, AD-9.
 *
 * **This module must never be reached from the client bundle.** Zod is
 * ~93 KB gzip, and shipping a validator to the browser to check values that
 * were already validated at build time would be indefensible (NFR-1). The
 * client reads plain constants from `src/config/index.ts`, which imports only
 * the *type* from here (`import type` is erased at compile time).
 *
 * Validation runs at build/dev start via `next.config.ts`, and again during
 * prerender via the root layout, so a malformed value fails `next build`
 * instead of shipping a broken WhatsApp CTA. There is deliberately no runtime
 * config fetch: that would add a failure mode to the critical path (AD-1).
 *
 * Every key must be `NEXT_PUBLIC_*` to be inlined into the client bundle
 * (Next.js env rules) — these are not secrets, and must never be (NFR-6).
 */

import { z } from "zod";

export const envSchema = z.object({
  /** FR-10 / Q3 — E.164 digits only; wa.me rejects "+" and spaces. */
  NEXT_PUBLIC_WHATSAPP_NUMBER: z
    .string()
    .regex(/^\d{8,15}$/, "must be E.164 digits only, e.g. 2348137553699"),
  NEXT_PUBLIC_SITE_URL: z.string().url(),
  /** FR-2 — attribution cookie TTL. */
  NEXT_PUBLIC_ATTRIBUTION_WINDOW_DAYS: z.coerce
    .number()
    .int()
    .min(1)
    .max(365),
  /** FR-15 — banner copy. */
  NEXT_PUBLIC_DISCOUNT_PERCENT: z.coerce.number().int().min(1).max(100),
  /** FR-16 — `QR5` style prefix. */
  NEXT_PUBLIC_DISCOUNT_PREFIX: z
    .string()
    .regex(/^[A-Z0-9]{1,10}$/, "uppercase alphanumerics only"),
  /** FR-16 / C-13 — spec floor is 4. */
  NEXT_PUBLIC_DISCOUNT_RAND_LEN: z.coerce.number().int().min(4).max(16),
  /** FR-18 / Q2 — render-only until terms land. */
  NEXT_PUBLIC_DISCOUNT_EXPIRY: z
    .string()
    .regex(/^\d{4}-\d{2}-\d{2}$/, "expected YYYY-MM-DD"),
  /** FR-13 / Q12 — deeplink failure timeout. */
  NEXT_PUBLIC_FALLBACK_TIMEOUT_MS: z.coerce.number().int().min(500).max(10_000),
  /** AD-7 / Q5 — adapter selection; `console` until the provider is chosen. */
  NEXT_PUBLIC_ANALYTICS_PROVIDER: z.enum(["console"]),
});

export type Env = z.infer<typeof envSchema>;

/**
 * Read `process.env` explicitly, key by key: Next.js statically replaces direct
 * member expressions, whereas passing the whole `process.env` object through
 * does not inline anything.
 */
export function readRawEnv(): Record<string, string | undefined> {
  return {
    NEXT_PUBLIC_WHATSAPP_NUMBER: process.env.NEXT_PUBLIC_WHATSAPP_NUMBER,
    NEXT_PUBLIC_SITE_URL: process.env.NEXT_PUBLIC_SITE_URL,
    NEXT_PUBLIC_ATTRIBUTION_WINDOW_DAYS:
      process.env.NEXT_PUBLIC_ATTRIBUTION_WINDOW_DAYS,
    NEXT_PUBLIC_DISCOUNT_PERCENT: process.env.NEXT_PUBLIC_DISCOUNT_PERCENT,
    NEXT_PUBLIC_DISCOUNT_PREFIX: process.env.NEXT_PUBLIC_DISCOUNT_PREFIX,
    NEXT_PUBLIC_DISCOUNT_RAND_LEN: process.env.NEXT_PUBLIC_DISCOUNT_RAND_LEN,
    NEXT_PUBLIC_DISCOUNT_EXPIRY: process.env.NEXT_PUBLIC_DISCOUNT_EXPIRY,
    NEXT_PUBLIC_FALLBACK_TIMEOUT_MS: process.env.NEXT_PUBLIC_FALLBACK_TIMEOUT_MS,
    NEXT_PUBLIC_ANALYTICS_PROVIDER: process.env.NEXT_PUBLIC_ANALYTICS_PROVIDER,
  };
}

/** Throws with an actionable message. Returns the parsed config on success. */
export function validateEnv(raw: Record<string, string | undefined> = readRawEnv()): Env {
  const result = envSchema.safeParse(raw);
  if (!result.success) {
    const detail = result.error.issues
      .map((issue) => `  ${issue.path.join(".")}: ${issue.message}`)
      .join("\n");
    throw new Error(
      `Invalid environment configuration — fix .env.local (see .env.example):\n${detail}`,
    );
  }
  return result.data;
}
