import type { Metadata } from "next";

import { ClientBootstrap } from "@/components/ClientBootstrap";
import { ATTRIBUTION_COOKIE, ATTRIBUTION_SESSION_KEY } from "@/lib/attribution";
import { buildBootScript } from "@/boot/attribution-boot";
import { config } from "@/config";
import { validateEnv } from "@/config/schema";
import { listActivePlacements } from "@/lib/placements";
import { site } from "@/data/content/site";
import "./globals.css";

/**
 * Second AD-9 gate: runs while prerendering, so even if someone bypasses
 * `next.config` (a custom entry point, `next start` against a stale build) a
 * malformed config still fails loudly rather than shipping silently.
 */
validateEnv();

/**
 * AD-3 / architect spec §9.1 — the attribution boot script is inlined into
 * `<head>` so it runs while the HTML parses, before first paint and before the
 * app bundle. This guarantees attribution is captured even if the bundle is
 * slow or fails, and that `/l/*` renders the right banner on first paint.
 *
 * `suppressHydrationWarning` on `<html>` is required because the script adds a
 * `data-route` attribute React did not render (the documented pattern for
 * pre-paint DOM fixes).
 */
const bootScript = buildBootScript({
  knownPlacements: listActivePlacements().map((p) => p.code),
  windowDays: config.NEXT_PUBLIC_ATTRIBUTION_WINDOW_DAYS,
  cookieName: ATTRIBUTION_COOKIE,
  sessionKey: ATTRIBUTION_SESSION_KEY,
});

export const metadata: Metadata = {
  metadataBase: new URL(config.NEXT_PUBLIC_SITE_URL),
  title: {
    default: site.metaTitleDefault,
    // `%s` is Next's title token; the separator/brand come from content (NFR-8).
    template: `%s | ${site.brand}`,
  },
  description: site.metaDescription,
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en" suppressHydrationWarning>
      <head>
        <script dangerouslySetInnerHTML={{ __html: bootScript }} />
      </head>
      <body className="flex min-h-screen flex-col bg-white text-zinc-900 antialiased dark:bg-zinc-950 dark:text-zinc-50">
        <ClientBootstrap />
        {children}
      </body>
    </html>
  );
}
