import { format, formatYear } from "@/lib/format";
import { config } from "@/config";

/**
 * Site-wide copy: chrome (header/footer), document metadata and shared link
 * labels — NFR-8 / plan T13. No component renders a literal; everything comes
 * from `src/data/content/*.ts` so a future locale is a new file, not a refactor.
 *
 * Placeholders are substituted here at module scope (`{percent}` ←
 * `NEXT_PUBLIC_DISCOUNT_PERCENT`, `{year}` ← `Intl`), so call sites render
 * plain strings.
 */

const percent = config.NEXT_PUBLIC_DISCOUNT_PERCENT;

export const site = {
  brand: "Danga",

  /* --- document metadata (SERP / browser tab) --- */
  metaTitleDefault: "Danga — your next property is one message away",
  metaDescription: format(
    "Scan a Danga QR code, browse the portfolio and talk to a real agent on WhatsApp. QR scans unlock an automatic {percent}% discount.",
    { percent },
  ),
  homeTitle: "Talk to a Danga agent",
  /** `/l` with no code, and `/l/<unknown>` — never a 404 (FR-4). */
  qrTitle: "Scan offer",
  /** Suffix for a known placement: `<label> — scan offer`. */
  qrTitleSuffix: "scan offer",
  qrDescription: format(
    "You scanned a Danga QR code. Claim your {percent}% discount and talk to a real agent on WhatsApp.",
    { percent },
  ),

  /* --- header --- */
  primaryNavLabel: "Primary",
  headerTermsLabel: "QR discount terms",
  headerPrivacyLabel: "Privacy",
  headerQrLabel: "QR generator",

  /* --- footer --- */
  footerNavLabel: "Footer",
  footerTermsLabel: "5% QR discount terms",
  footerPrivacyLabel: "Privacy policy",
  footerQrLabel: "QR generator",
  copyright: format("© {year} Danga. All rights reserved.", {
    year: formatYear(),
  }),

  /* --- shared link --- */
  backToChat: "Back to chat with an agent",
} as const;
